package com.allinone.supply.controller;
import com.allinone.common.core.controller.BaseController; import com.allinone.common.core.domain.AjaxResult; import com.allinone.supply.domain.WorkflowConfig; import com.allinone.supply.service.IWorkflowConfigService; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/supply/config/workflows") public class WorkflowConfigController extends BaseController { @Autowired private IWorkflowConfigService service; @PreAuthorize("@ss.hasPermi('supply:config:workflow')") @GetMapping public AjaxResult list(){return success(service.list());} @PreAuthorize("@ss.hasPermi('supply:config:workflow')") @PutMapping public AjaxResult save(@RequestBody WorkflowConfig config){config.setUpdatedBy(getUserId());return toAjax(service.save(config));} }
